(()=>{'use strict';
const U='https://gfggmkeucgqkkyvummpu.supabase.co',K='sb_publishable_ptCVbq9h15prKhT0OO5Zmg_LkE3cbK0';
const esc=s=>String(s??'').replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',"'":'&#39;'}[c]));
const enc=s=>encodeURIComponent(String(s??''));
const icon={Pendidikan:'graduation-cap',Kesehatan:'heart-pulse',Infrastruktur:'landmark',Ekonomi:'chart-no-axes-combined',Sosial:'users',Lingkungan:'leaf',Kemiskinan:'house',Pertanian:'wheat',Bencana:'cloud-lightning',Air:'droplets',Transportasi:'bus-front'};
const fields=[['Pendidikan','Pendidikan','Akses, mutu, sekolah dan pembelajaran.'],['Kesehatan','Kesehatan','Layanan, fasilitas dan kesehatan masyarakat.'],['Infrastruktur','Infrastruktur','Jalan, jembatan, fasilitas dan konektivitas.'],['Ekonomi','Ekonomi','Usaha, pekerjaan, harga dan kesejahteraan.'],['Sosial','Sosial','Masyarakat, layanan sosial dan kehidupan warga.'],['Lingkungan','Lingkungan','Sampah, pencemaran, ruang hijau dan ekosistem.'],['Kemiskinan','Kemiskinan','Kondisi sosial-ekonomi dan akses kebutuhan dasar.'],['Pertanian','Pertanian','Produksi, petani, lahan dan pangan.'],['Bencana','Bencana','Banjir, longsor, kekeringan dan risiko wilayah.'],['Air Bersih','Air Bersih','Ketersediaan dan akses air bersih.'],['Transportasi','Transportasi','Mobilitas, angkutan dan keselamatan jalan.']];
async function api(path){const r=await fetch(U+path,{headers:{apikey:K,Authorization:`Bearer ${K}`,Accept:'application/json'}});if(!r.ok)throw Error(`HTTP ${r.status}`);return r.json()}
function wire(){document.querySelectorAll('#home [data-view]').forEach(b=>b.onclick=()=>window.render?.(b.dataset.view,b.dataset.arg||''));try{window.lucide?.createIcons()}catch{}}
function home(){const h=document.getElementById('home');if(!h)return;h.innerHTML=`<div class="lux-home">
<section class="lux-hero"><div class="hero-overlay"></div><div class="hero-content"><div class="lux-kicker"><span></span> WASKITA • INDONESIA PUNYA MASALAH</div><h1>Lihat apa yang terjadi.<br><strong>Pahami sebelum terlambat.</strong></h1><p>Portal publik untuk menemukan masalah Indonesia, memahami dampaknya, melihat perubahan, dan menyampaikan informasi dari masyarakat.</p><form class="lux-search" id="luxSearch"><i data-lucide="search"></i><input id="luxQuestion" placeholder="Cari masalah, wilayah, atau topik…"><button>Cari</button></form><div class="hero-cta"><button data-view="problems">Jelajahi Masalah <b>→</b></button><button data-view="report" class="secondary">Suara Warga <b>↗</b></button></div></div><div class="hero-mark">W<br><small>WASKITA</small></div></section>
<section class="lux-intro"><div><span class="lux-label">PETA MASALAH INDONESIA</span><h2>Mulai dari masalahnya.</h2><p>WASKITA membantu publik melihat persoalan berdasarkan bidang yang nyata di kehidupan sehari-hari.</p></div><button data-view="map" class="text-link">Jelajahi peta Indonesia <b>→</b></button></section>
<section class="field-grid">${fields.map(([n,t,d])=>`<button class="field-card" data-view="problems" data-arg="${esc(n)}"><span class="field-no">${String(fields.findIndex(x=>x[0]===n)+1).padStart(2,'0')}</span><span class="field-icon"><i data-lucide="${icon[n]||'circle'}"></i></span><span class="field-copy"><b>${t}</b><small>${d}</small></span><span class="field-arrow">↗</span></button>`).join('')}</section>
<section class="lux-split"><article class="map-feature"><div class="feature-copy"><span class="lux-label">WILAYAH</span><h2>Indonesia dalam satu pandangan.</h2><p>Masuk dari provinsi, kabupaten/kota, kecamatan hingga desa/kelurahan.</p><button data-view="map">Buka Peta Indonesia <b>→</b></button></div><div class="map-visual"><div class="map-lines"></div><div class="map-pin p1">JKT</div><div class="map-pin p2">JTG</div><div class="map-pin p3">PWR</div><div class="map-caption">PETA PUBLIK · WILAYAH INDONESIA</div></div></article>
<article class="voice-feature"><div class="voice-icon"><i data-lucide="mic-2"></i></div><span class="lux-label">SUARA WARGA</span><h2>Temukan masalah. Sampaikan yang Anda lihat.</h2><p>Kirim laporan dengan cerita, lokasi, foto dan video. Laporan warga tetap dibedakan dari data yang telah diverifikasi.</p><button data-view="report">Kirim Laporan <b>→</b></button><div class="voice-rule"><span>01 KIRIM</span><span>02 DITINJAU</span><span>03 DIPANTAU</span></div></article></section>
<section class="latest"><div class="lux-intro"><div><span class="lux-label">PEMANTAUAN PUBLIK</span><h2>Perubahan terbaru.</h2><p>Masalah yang baru diperbarui dalam data publik WASKITA.</p></div><button data-view="monitoring" class="text-link">Pantau perubahan <b>→</b></button></div><div id="homeIssues" class="latest-grid"><div class="latest-empty">Memuat data publik…</div></div></section>
<section class="lux-closing"><div><span class="lux-label">WASKITA</span><h2>Lihat. Pahami. Antisipasi.</h2><p>Satu ruang publik untuk masalah, wilayah, data, suara warga, dan perubahan.</p></div><div><button data-view="data">Data &amp; Statistik</button><button data-view="more" class="light">Tentang WASKITA</button></div></section>
</div>`;wire();load();document.getElementById('luxSearch')?.addEventListener('submit',e=>{e.preventDefault();const q=document.getElementById('luxQuestion')?.value.trim();if(q)window.render?.('result',q)})}
async function load(){const box=document.getElementById('homeIssues');if(!box)return;try{const rows=await api('/rest/v1/problems?select=id,title,category,status,updated_at,region_id&order=updated_at.desc&limit=6');box.innerHTML=rows.length?rows.map(x=>`<button class="latest-card" data-problem="${esc(x.id)}"><span class="latest-icon"><i data-lucide="${icon[x.category]||'alert-circle'}"></i></span><span><b>${esc(x.title||'Masalah tanpa judul')}</b><small>${esc(x.category||'Masalah')} · ${esc(x.status||'tercatat')} · ${x.updated_at?new Date(x.updated_at).toLocaleDateString('id-ID'):''}</small></span><em>Detail →</em></button>`).join(''):'<div class="latest-empty">Belum ada masalah publik yang tersedia.</div>';box.querySelectorAll('[data-problem]').forEach(b=>b.onclick=()=>window.render?.('problem-detail',b.dataset.problem));try{window.lucide?.createIcons()}catch{}}catch{box.innerHTML='<div class="latest-empty">Data publik belum dapat dimuat. Silakan coba lagi.</div>'}}
const old=window.render;window.render=async function(v,x=''){if(v==='home'){home();window.scrollTo({top:0,behavior:'smooth'});return}if(v==='problems'&&x){if(typeof old==='function')return old('problems',x)}if(typeof old==='function')return old(v,x)};document.addEventListener('DOMContentLoaded',home)})();